PREFIX ssn: <http://www.w3.org/ns/ssn/>
PREFIX ssn-system: <http://www.w3.org/ns/ssn/system/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>

SELECT ?property ?definition
WHERE {
  ?property rdfs:subClassOf ssn-system:SystemProperty .
  ?property rdfs:subClassOf ssn-system:OperatingProperty .
  OPTIONAL { ?property rdfs:isDefinedBy ?definition }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX saref4city: <https://w3id.org/def/saref4city#>

SELECT ?cityProperty ?administrativeAreaProperty ?additionalCityInfo
WHERE {
  {
    SELECT ?cityProperty
    WHERE {
      saref4city:City rdfs:subClassOf* ?restriction .
      ?restriction owl:onProperty ?cityProperty .
    }
  }
  UNION
  {
    SELECT ?administrativeAreaProperty
    WHERE {
      saref4city:AdministrativeArea rdfs:subClassOf* ?restriction .
      ?restriction owl:onProperty ?administrativeAreaProperty .
    }
  }
  UNION
  {
    SELECT ?additionalCityInfo
    WHERE {
      saref4city:City rdfs:subClassOf* ?restriction .
      ?restriction owl:onProperty ?additionalCityInfo .
      FILTER NOT EXISTS {
        saref4city:AdministrativeArea rdfs:subClassOf* [ owl:onProperty ?additionalCityInfo ]
      }
    }
  }
}

PREFIX ssn: <http://www.w3.org/ns/ssn/>
PREFIX ssn-system: <http://www.w3.org/ns/ssn/system/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>

SELECT ?property ?interaction
WHERE {
  ?property rdfs:subClassOf ssn-system:SystemProperty .
  OPTIONAL {
    ?property rdfs:subClassOf [
      a owl:Restriction ;
      owl:onProperty ?interaction ;
      owl:someValuesFrom ?otherProperty
    ] .
    ?otherProperty rdfs:subClassOf ssn-system:SystemProperty .
  }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX saref4city: <https://w3id.org/def/saref4city#>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>

SELECT ?countryProperty ?cityProperty ?additionalInfo
WHERE {
  { 
    saref4city:Country rdfs:subClassOf ?restriction .
    ?restriction owl:onProperty ?countryProperty .
    FILTER NOT EXISTS {
      saref4city:City rdfs:subClassOf [ owl:onProperty ?countryProperty ]
    }
  }
  UNION
  { 
    saref4city:City rdfs:subClassOf ?restriction .
    ?restriction owl:onProperty ?cityProperty .
    FILTER NOT EXISTS {
      saref4city:Country rdfs:subClassOf [ owl:onProperty ?cityProperty ]
    }
  }
  UNION
  { 
    saref4city:Country rdfs:subClassOf [ owl:onProperty ?additionalInfo ] .
    saref4city:City rdfs:subClassOf [ owl:onProperty ?additionalInfo ] .
    FILTER (saref4city:Country != saref4city:City)
  }
}

